import type { BankQuestion } from "@/lib/bank";

/** Mole Concept and Stoichiometry (Chemistry (JEE/NEET)): 129 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"chem-mole-concept-1","question":"The number of moles present in 22 g of CO₂ (molar mass 44 g/mol) is:","options":["0.25","0.5","1.0","2.0"],"answer":1,"explanation":"Moles = mass ÷ molar mass = 22/44 = 0.5 mol.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-2","question":"4 g of NaOH (molar mass 40 g/mol) is dissolved in water to make 500 mL of solution. The molarity of the solution is:","options":["0.05 M","0.1 M","0.2 M","0.4 M"],"answer":2,"explanation":"Moles of NaOH = 4/40 = 0.1 mol; molarity = 0.1 mol ÷ 0.5 L = 0.2 M. The trap is dividing by 500 instead of 0.5 L.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-3","question":"The number of oxygen atoms in 0.5 mol of O₂ gas is (N_A = 6.022 × 10²³):","options":["3.011 × 10²³","6.022 × 10²³","1.204 × 10²⁴","2.408 × 10²⁴"],"answer":1,"explanation":"0.5 mol O₂ contains 0.5 N_A molecules, and each molecule has 2 atoms, so atoms = 2 × 0.5 × 6.022 × 10²³ = 6.022 × 10²³.","difficulty":"easy","source":"NEET"},
  {"id":"chem-mole-concept-4","question":"A compound contains 40% carbon, 6.67% hydrogen and 53.33% oxygen by mass. Its empirical formula is:","options":["CH₂O","C₂H₄O","CHO","CH₃O"],"answer":0,"explanation":"Moles per 100 g: C = 40/12 = 3.33, H = 6.67/1 = 6.67, O = 53.33/16 = 3.33. Ratio C:H:O = 1:2:1, so the empirical formula is CH₂O.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-5","question":"2 mol of H₂ and 2 mol of O₂ are allowed to react to form water (2H₂ + O₂ → 2H₂O). Which statement is correct?","options":["O₂ is the limiting reagent and 2 mol of H₂O form","H₂ is the limiting reagent and 2 mol of H₂O form","H₂ is the limiting reagent and 4 mol of H₂O form","Neither reagent is limiting and 4 mol of H₂O form"],"answer":1,"explanation":"2 mol H₂ needs only 1 mol O₂, so H₂ is consumed first and is limiting. 2 mol H₂ gives 2 mol H₂O; 1 mol O₂ is left over.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-6","question":"9.8 g of H₂SO₄ (molar mass 98 g/mol) is dissolved in 500 g of water. The molality of the solution is:","options":["0.5 m","1.0 m","0.1 m","0.2 m"],"answer":3,"explanation":"Moles of H₂SO₄ = 9.8/98 = 0.1 mol; molality = moles of solute ÷ kg of solvent = 0.1/0.5 = 0.2 m.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-7","question":"The volume of O₂ at STP (1 mol = 22.4 L) required for the complete combustion of 1 mol of methane is:","options":["11.2 L","22.4 L","44.8 L","67.2 L"],"answer":2,"explanation":"CH₄ + 2O₂ → CO₂ + 2H₂O, so 1 mol CH₄ needs 2 mol O₂ = 2 × 22.4 = 44.8 L at STP.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-mole-concept-8","question":"The equivalent mass of KMnO₄ (molar mass 158 g/mol) when it acts as an oxidising agent in acidic medium is:","options":["158","79","52.7","31.6"],"answer":3,"explanation":"In acidic medium MnO₄⁻ → Mn²⁺ is a 5-electron change, so equivalent mass = 158/5 = 31.6. (In neutral medium it is 158/3 = 52.7 and in alkaline medium 158/1 = 158.)","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-9","question":"100 mL of 0.5 M HCl is diluted with water to a final volume of 500 mL. The molarity of the diluted solution is:","options":["0.1 M","0.25 M","1.0 M","2.5 M"],"answer":0,"explanation":"M₁V₁ = M₂V₂: 0.5 × 100 = M₂ × 500, so M₂ = 0.1 M. Dilution does not change the number of moles of solute.","difficulty":"moderate","source":"NEET"},
  {"id":"chem-mole-concept-10","question":"A sample of limestone is 80% CaCO₃ by mass (the rest is inert). The mass of this sample needed to produce 11.2 L of CO₂ at STP on strong heating is:","options":["40 g","50 g","62.5 g","80 g"],"answer":2,"explanation":"CaCO₃ → CaO + CO₂; 11.2 L CO₂ at STP = 0.5 mol, so 0.5 mol CaCO₃ = 50 g is needed. Since the sample is only 80% pure, sample mass = 50/0.8 = 62.5 g.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-11","question":"A solution is made by mixing 36 g of water and 46 g of ethanol (C₂H₅OH, molar mass 46). The mole fraction of ethanol is:","options":["0.25","0.33","0.50","0.67"],"answer":1,"explanation":"Moles of water = 36/18 = 2; moles of ethanol = 46/46 = 1. Mole fraction of ethanol = 1/(1 + 2) = 1/3 ≈ 0.33. Using masses instead of moles gives the wrong 0.56.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-12","question":"The molarity of pure water (density 1 g/mL) is approximately:","options":["1 M","18 M","55.5 M","100 M"],"answer":2,"explanation":"1 L of water has mass 1000 g = 1000/18 = 55.5 mol, so its molarity is 55.5 mol/L.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-13","question":"The ratio of the number of molecules in 1 g of H₂ to the number of molecules in 1 g of O₂ is:","options":["1 : 16","1 : 1","2 : 1","16 : 1"],"answer":3,"explanation":"1 g H₂ = 1/2 mol; 1 g O₂ = 1/32 mol. Ratio = (1/2) : (1/32) = 16 : 1. Equal masses of gases do not contain equal numbers of molecules.","difficulty":"hard","source":"NEET"},
  {"id":"chem-mole-concept-14","question":"Which of the following samples contains the greatest number of atoms?","options":["1 g of He","1 g of O₂","1 g of N₂","1 g of H₂"],"answer":3,"explanation":"Moles of atoms: He = 1/4 = 0.25; O₂ = 2 × 1/32 = 0.0625; N₂ = 2 × 1/28 ≈ 0.071; H₂ = 2 × 1/2 = 1.0. 1 g of H₂ has the most atoms.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-15","question":"The volume of 0.5 M FeSO₄ solution that is completely oxidised by 20 mL of 0.1 M KMnO₄ in acidic medium is:","options":["4 mL","10 mL","20 mL","100 mL"],"answer":2,"explanation":"MnO₄⁻ + 5Fe²⁺ + 8H⁺ → Mn²⁺ + 5Fe³⁺ + 4H₂O. Moles KMnO₄ = 0.1 × 0.020 = 0.002 mol, which oxidises 5 × 0.002 = 0.01 mol Fe²⁺. Volume = 0.01/0.5 = 0.02 L = 20 mL.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-16","question":"A 2 M aqueous NaOH solution (molar mass 40) has density 1.08 g/mL. Its molality is:","options":["1.85 m","2.0 m","2.16 m","2.5 m"],"answer":1,"explanation":"Take 1 L of solution: mass = 1080 g, NaOH = 2 mol = 80 g, so water = 1000 g = 1 kg. Molality = 2 mol/1 kg = 2.0 m.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-mole-concept-17","question":"3.0 g of a metal oxide on complete reduction by hydrogen gives 2.4 g of the metal. The equivalent mass of the metal is:","options":["8","16","32","64"],"answer":2,"explanation":"Oxygen in the oxide = 3.0 − 2.4 = 0.6 g. Equivalent mass of metal = (mass of metal/mass of oxygen) × 8 = (2.4/0.6) × 8 = 32.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-18","question":"The percentage by mass of water of crystallisation in CuSO₄·5H₂O (molar mass 249.5 g/mol) is approximately:","options":["18%","36%","54%","72%"],"answer":1,"explanation":"Water = 5 × 18 = 90 g per mole of hydrate. Percentage = (90/249.5) × 100 ≈ 36%.","difficulty":"hard","source":"NEET"},
  {"id":"chem-mole-concept-19","question":"A 10 g sample containing CaCO₃ and inert matter is heated strongly until no further loss of mass occurs; the sample loses 2.2 g. The percentage of CaCO₃ in the sample is:","options":["22%","44%","50%","62.5%"],"answer":2,"explanation":"The loss is CO₂: 2.2 g = 2.2/44 = 0.05 mol, so CaCO₃ = 0.05 mol = 5 g. Percentage = (5/10) × 100 = 50%. Choosing 22% treats the lost mass as CaCO₃ itself.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-20","question":"How many of the following statements are correct? (A) 1 mol of O₂ and 1 mol of O₃ contain the same number of molecules. (B) 1 g of CH₄ and 1 g of CO₂ contain the same number of molecules. (C) The molar mass in g/mol is numerically equal to the relative molecular mass. (D) The molality of a solution changes with temperature.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"(A) true: 1 mol of anything has N_A particles. (B) false: 1/16 mol vs 1/44 mol. (C) true. (D) false: molality uses mass of solvent, which is temperature independent (molarity changes with temperature). Two are correct.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-21","question":"28 g of N₂ and 9 g of H₂ are reacted to form NH₃ (N₂ + 3H₂ → 2NH₃) and the reaction goes to completion. The mass of the excess reactant left is:","options":["3 g","1.5 g","6 g","0 g"],"answer":0,"explanation":"N₂ = 1 mol, H₂ = 4.5 mol. 1 mol N₂ needs 3 mol H₂, so N₂ is limiting and 2 mol NH₃ (34 g) forms. H₂ left = 4.5 − 3 = 1.5 mol = 3 g.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-22","question":"The volume of 0.02 M KMnO₄ solution required to completely oxidise 25 mL of 0.1 M oxalic acid (H₂C₂O₄) in acidic medium is:","options":["10 mL","25 mL","50 mL","125 mL"],"answer":2,"explanation":"2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O. Moles oxalic acid = 0.1 × 0.025 = 0.0025 mol, each gives 2 electrons = 0.005 mol e⁻. KMnO₄ takes 5 e⁻ each: 0.005/5 = 0.001 mol, so V = 0.001/0.02 = 0.05 L = 50 mL.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-23","question":"A hydrocarbon contains 92.3% carbon and 7.7% hydrogen by mass and has vapour density 39. Its molecular formula is:","options":["C₂H₂","C₆H₆","C₄H₄","C₈H₈"],"answer":1,"explanation":"C: 92.3/12 = 7.69, H: 7.7/1 = 7.7, ratio 1:1, empirical formula CH (mass 13). Molar mass = 2 × vapour density = 78, so n = 78/13 = 6 and the formula is C₆H₆ (benzene). C₂H₂ has the same empirical formula but molar mass 26.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-24","question":"Assertion (A): Molality is preferred over molarity when studying how a property of a solution varies with temperature. Reason (R): Molality is based on the mass of solvent, which does not change with temperature.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Molarity uses solution volume, which expands or contracts with temperature; molality uses solvent mass, which is unchanged. So R correctly explains why molality is preferred.","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-mole-concept-25","question":"A triatomic gas has vapour density 22. The total number of atoms in 11.2 L of this gas at STP is (N_A = 6.02 × 10²³):","options":["3.01 × 10²³","6.02 × 10²³","1.8 × 10²⁴","9.03 × 10²³"],"answer":3,"explanation":"Molar mass = 2 × 22 = 44 (e.g. CO₂). 11.2 L at STP = 0.5 mol of molecules = 0.5 × 3 = 1.5 mol of atoms = 1.5 × 6.02 × 10²³ = 9.03 × 10²³ atoms.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-26","question":"Match the concentration term (Column I) with its description (Column II). (a) Molarity, (b) Molality, (c) Mole fraction, (d) Normality. (1) Unit mol/kg, independent of temperature; (2) based on gram equivalents per litre; (3) dimensionless, sum over all components is 1; (4) unit mol/L, depends on temperature.","options":["a-4, b-1, c-3, d-2","a-1, b-4, c-3, d-2","a-4, b-1, c-2, d-3","a-2, b-1, c-3, d-4"],"answer":0,"explanation":"Molarity is mol/L and temperature dependent (4); molality is mol/kg and temperature independent (1); mole fraction is dimensionless (3); normality is equivalents per litre (2).","difficulty":"very-hard","source":"NEET"},
  {"id":"chem-mole-concept-27","question":"The volume of air (20% O₂ by volume) at STP required for the complete combustion of 2.24 L of propane (C₃H₈) at STP is:","options":["11.2 L","22.4 L","56 L","112 L"],"answer":2,"explanation":"C₃H₈ + 5O₂ → 3CO₂ + 4H₂O. 2.24 L propane = 0.1 mol needs 0.5 mol O₂ = 11.2 L. Air is 20% O₂, so air needed = 11.2/0.2 = 56 L.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-mole-concept-28","question":"A 20% (w/w) aqueous NaOH solution (molar mass 40) has density 1.2 g/mL. The molarity of the solution is:","options":["2.4 M","5.0 M","6.0 M","8.0 M"],"answer":2,"explanation":"Take 100 g of solution: NaOH = 20 g = 0.5 mol; volume = 100/1.2 = 83.3 mL = 0.0833 L. Molarity = 0.5/0.0833 = 6.0 M. (Shortcut: M = 10 × d × % / molar mass = 10 × 1.2 × 20/40 = 6.)","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-29","question":"The number of oxygen atoms in 4.9 g of H₂SO₄ (molar mass 98) is (N_A = 6.02 × 10²³):","options":["3.01 × 10²²","6.02 × 10²²","2.4 × 10²³","1.2 × 10²³"],"answer":3,"explanation":"4.9 g = 4.9/98 = 0.05 mol H₂SO₄. Each molecule has 4 O atoms, so O atoms = 4 × 0.05 × 6.02 × 10²³ = 0.2 × 6.02 × 10²³ ≈ 1.2 × 10²³.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-30","question":"0.2 mol of a gaseous hydrocarbon on complete combustion gives 0.6 mol of CO₂ and 0.8 mol of H₂O. The hydrocarbon and the moles of O₂ consumed are:","options":["C₃H₈, 1.0 mol O₂","C₃H₈, 0.5 mol O₂","C₃H₆, 0.9 mol O₂","C₂H₆, 0.7 mol O₂"],"answer":0,"explanation":"Per mole of hydrocarbon: C = 0.6/0.2 = 3, H = 2 × 0.8/0.2 = 8, so it is C₃H₈. C₃H₈ + 5O₂ → 3CO₂ + 4H₂O, so 0.2 mol consumes 0.2 × 5 = 1.0 mol O₂.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-31","question":"The number of molecules in 9 g of water (molar mass 18 g/mol) is (N_A = 6.022 × 10²³):","options":["6.022 × 10²³","1.204 × 10²⁴","1.505 × 10²³","3.011 × 10²³"],"answer":3,"explanation":"9 g = 0.5 mol, so 0.5 × 6.022 × 10²³ = 3.011 × 10²³ molecules.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-32","question":"The volume occupied by 3.2 g of SO₂ (molar mass 64 g/mol) at STP is (1 mol = 22.4 L):","options":["0.56 L","2.24 L","11.2 L","1.12 L"],"answer":3,"explanation":"n = 3.2/64 = 0.05 mol; V = 0.05 × 22.4 = 1.12 L.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-33","question":"When oxalic acid (H₂C₂O₄) acts as a reducing agent and is oxidised to CO₂, its n-factor is:","options":["2","5","4","1"],"answer":0,"explanation":"C goes from +3 to +4; with two C atoms, 2 electrons are lost per molecule, so n-factor = 2 (equivalent mass = 90/2 = 45 for the anhydrous acid).","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-34","question":"The mole fraction of the solute in a 1 molal aqueous solution is about:","options":["0.018","0.1","0.055","0.982"],"answer":0,"explanation":"1 mol solute in 1000 g water (55.5 mol): x = 1/(1 + 55.5) = 0.0177 ≈ 0.018. 0.982 is the mole fraction of water.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-35","question":"An oxide of nitrogen contains 30.4% nitrogen by mass. Its empirical formula is:","options":["N₂O₅","NO","N₂O","NO₂"],"answer":3,"explanation":"N : O = 30.4/14 : 69.6/16 = 2.17 : 4.35 = 1 : 2, so the empirical formula is NO₂.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-36","question":"The mass of NaOH (molar mass 40) needed to neutralise 100 mL of 0.1 M H₂SO₄ completely is:","options":["1.6 g","0.8 g","0.4 g","0.2 g"],"answer":1,"explanation":"n(H₂SO₄) = 0.01 mol, which needs 0.02 mol NaOH (dibasic acid) = 0.8 g. 0.4 g treats the acid as monobasic.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-37","question":"The normality of a 0.3 M solution of phosphorous acid (H₃PO₃) used as an acid is:","options":["0.3 N","0.6 N","0.1 N","0.9 N"],"answer":1,"explanation":"H₃PO₃ has only two ionisable P–OH hydrogens (the third H is bonded to P), so its basicity is 2 and N = 2 × 0.3 = 0.6 N. 0.9 N wrongly assumes three.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-38","question":"200 mL of 0.2 M NaCl is mixed with 300 mL of 0.1 M NaCl. The molarity of the resulting solution is:","options":["0.14 M","0.12 M","0.15 M","0.30 M"],"answer":0,"explanation":"Total moles = 0.04 + 0.03 = 0.07 mol in 0.5 L = 0.14 M. Averaging the molarities (0.15 M) ignores the different volumes.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-39","question":"A 10 g mixture of NaHCO₃ and Na₂CO₃ loses 1.24 g on strong heating. The percentage of NaHCO₃ in the mixture is (Na = 23):","options":["16.8%","33.6%","66.4%","50%"],"answer":1,"explanation":"2NaHCO₃ → Na₂CO₃ + H₂O + CO₂: 168 g of NaHCO₃ loses 62 g (H₂O + CO₂). Mass of NaHCO₃ = 1.24 × 168/62 = 3.36 g = 33.6%. Na₂CO₃ does not decompose.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-mole-concept-40","question":"How many of the following statements are correct? (A) Molarity changes with temperature, but molality does not. (B) One mole of any ideal gas occupies 22.4 L at 273 K and 1 bar. (C) Mass percentage of a solution does not depend on temperature. (D) The equivalent mass of an acid can depend on the reaction in which it takes part.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, C and D are correct (e.g. H₃PO₄ has different equivalent masses depending on how many H⁺ are replaced). B is wrong: at 273 K and 1 bar the molar volume is 22.7 L; 22.4 L is for 1 atm.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-41","question":"10 g of CaCO₃ is treated with 100 mL of 1 M HCl. The volume of CO₂ evolved at STP is:","options":["2.24 L","4.48 L","0.56 L","1.12 L"],"answer":3,"explanation":"CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂. n(CaCO₃) = 0.1, n(HCl) = 0.1 (needs 0.2), so HCl is limiting and gives 0.05 mol CO₂ = 1.12 L. 2.24 L wrongly takes CaCO₃ as limiting.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-42","question":"25 mL of an Fe²⁺ solution requires 20 mL of 0.02 M K₂Cr₂O₇ for complete oxidation in acidic medium. The molarity of the Fe²⁺ solution is:","options":["0.032 M","0.016 M","0.096 M","0.048 M"],"answer":2,"explanation":"Cr₂O₇²⁻ + 6Fe²⁺ → ... : n(Cr₂O₇²⁻) = 4 × 10⁻⁴, so n(Fe²⁺) = 2.4 × 10⁻³ mol in 25 mL = 0.096 M. 0.016 M ignores the 1 : 6 ratio.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-43","question":"Assertion (A): The equivalent mass of H₃PO₄ (molar mass 98) in its reaction with NaOH to form NaH₂PO₄ is 98. Reason (R): H₃PO₄ is tribasic, so its equivalent mass is always 98/3.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true: only one H⁺ is replaced in forming NaH₂PO₄, so n-factor = 1. R is false: the equivalent mass depends on the reaction (98, 49 or 32.7).","difficulty":"very-hard","source":"NEET · JEE Main"},
  {"id":"chem-mole-concept-44","question":"0.29 g of an organic compound containing C, H and O gives 0.66 g of CO₂ and 0.27 g of H₂O on complete combustion. Its molar mass is 58 g/mol. The molecular formula is:","options":["C₂H₂O₂","C₃H₆O","C₄H₁₀","C₃H₈O"],"answer":1,"explanation":"C = 0.66 × 12/44 = 0.18 g (0.015 mol); H = 0.27 × 2/18 = 0.03 g (0.03 mol); O = 0.29 − 0.21 = 0.08 g (0.005 mol). Ratio 3 : 6 : 1 → C₃H₆O = 58. C₂H₂O₂ and C₄H₁₀ also weigh 58 but do not fit the analysis.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-45","question":"The number of electrons in 1.8 mL of water (density 1 g/mL) is (N_A = 6.022 × 10²³):","options":["6.022 × 10²³","6.022 × 10²²","6.022 × 10²⁴","1.084 × 10²³"],"answer":0,"explanation":"1.8 g = 0.1 mol H₂O; each molecule has 10 electrons (8 + 1 + 1), so 1 mol electrons = 6.022 × 10²³.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id": "chem-mole-concept-46", "question": "One atomic mass unit (1 u), defined as 1/12 of the mass of one ¹²C atom, is approximately equal to:", "options": ["6.022 × 10⁻²³ g", "1.66 × 10⁻²⁷ g", "1.66 × 10⁻²⁴ g", "1.99 × 10⁻²³ g"], "answer": 2, "explanation": "1 u = 1 g ÷ N_A = 1/(6.022 × 10²³) g ≈ 1.66 × 10⁻²⁴ g. The value 1.66 × 10⁻²⁷ is the same quantity in kilograms, not grams; 1.99 × 10⁻²³ g is the mass of a whole ¹²C atom.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-mole-concept-47", "question": "The number of significant figures in 0.00250 is:", "options": ["2", "3", "5", "6"], "answer": 1, "explanation": "Leading zeros only fix the decimal point and are not significant; the trailing zero after the decimal point is significant. So 2, 5 and the final 0 count: 3 significant figures.", "difficulty": "easy", "source": "NEET"},
  {"id": "chem-mole-concept-48", "question": "Carbon forms CO and CO₂. With a fixed 12 g of carbon, the masses of oxygen that combine are 16 g and 32 g, in the simple ratio 1 : 2. This illustrates the law of:", "options": ["Definite proportions", "Multiple proportions", "Reciprocal proportions", "Gaseous volumes"], "answer": 1, "explanation": "When two elements form more than one compound, the masses of one element combining with a fixed mass of the other are in a simple whole-number ratio (Dalton's law of multiple proportions). Definite proportions is about one compound having a fixed composition.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-mole-concept-49", "question": "A sample of drinking water contains 15 ppm (by mass) of chloroform. Its concentration expressed as a percentage by mass is:", "options": ["1.5 × 10⁻² %", "0.15 %", "1.5 × 10⁻⁴ %", "1.5 × 10⁻³ %"], "answer": 3, "explanation": "15 ppm means 15 g per 10⁶ g of solution. Mass % = (15/10⁶) × 100 = 1.5 × 10⁻³ %.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-mole-concept-50", "question": "Natural chlorine is 75% ³⁵Cl and 25% ³⁷Cl (by number of atoms). The average atomic mass of chlorine is:", "options": ["35.5 u", "36.0 u", "35.25 u", "36.5 u"], "answer": 0, "explanation": "Average atomic mass = 0.75 × 35 + 0.25 × 37 = 26.25 + 9.25 = 35.5 u. 36.0 u is the simple (unweighted) mean of the two isotopes.", "difficulty": "moderate", "source": "NEET"},
  {"id": "chem-mole-concept-51", "question": "The mass of a single water molecule (molar mass 18 g/mol, N_A = 6.022 × 10²³) is about:", "options": ["1.08 × 10⁻²² g", "2.99 × 10⁻²³ g", "3.0 × 10⁻²² g", "1.66 × 10⁻²⁴ g"], "answer": 1, "explanation": "Mass of one molecule = 18 g ÷ 6.022 × 10²³ = 2.99 × 10⁻²³ g.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-mole-concept-52", "question": "0.1 mol of CaCl₂ and 0.1 mol of NaCl are dissolved together in water and the volume is made up to 500 mL. The molar concentration of chloride ions is:", "options": ["0.3 M", "0.4 M", "0.6 M", "1.2 M"], "answer": 2, "explanation": "Cl⁻ from CaCl₂ = 0.2 mol, from NaCl = 0.1 mol; total 0.3 mol in 0.5 L gives [Cl⁻] = 0.6 M. 0.3 M forgets to divide by 0.5 L; 0.4 M treats each salt as giving one Cl⁻.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "chem-mole-concept-53", "question": "10 g of CaCO₃ is strongly heated and 3.92 g of CaO is obtained (Ca = 40). The percentage yield of the decomposition is:", "options": ["39.2%", "56%", "70%", "80%"], "answer": 2, "explanation": "CaCO₃ → CaO + CO₂: 10 g = 0.1 mol CaCO₃ should give 0.1 mol = 5.6 g CaO. Yield = 3.92/5.6 × 100 = 70%. 39.2% wrongly compares 3.92 g with the 10 g of reactant.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-mole-concept-54", "question": "When Fe₃O₄ is oxidised completely to Fe₂O₃, its equivalent mass in terms of its molar mass M is:", "options": ["M/8", "M/3", "M/2", "M"], "answer": 3, "explanation": "In Fe₃O₄ the three Fe atoms carry a total charge of +8; in Fe₂O₃ each Fe is +3, so three Fe atoms reach +9. Total electrons lost per Fe₃O₄ = 9 − 8 = 1, so the n-factor is 1 and the equivalent mass is M. M/8 wrongly uses the total oxidation number as the n-factor.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-mole-concept-55", "question": "The hydrated salt Na₂SO₄·xH₂O weighs 2.68 g; on heating it loses all its water and 1.42 g of anhydrous Na₂SO₄ (molar mass 142) remains. The value of x is:", "options": ["10", "7", "5", "2"], "answer": 1, "explanation": "Anhydrous salt = 1.42/142 = 0.01 mol. Water lost = 2.68 − 1.42 = 1.26 g = 1.26/18 = 0.07 mol. x = 0.07/0.01 = 7. 10 (Glauber's salt) is the familiar hydrate but does not fit these data.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-mole-concept-56", "question": "An aqueous solution has mole fraction of solute 0.2. Its molality is about:", "options": ["13.9 m", "11.1 m", "0.25 m", "12.5 m"], "answer": 0, "explanation": "Take 1 mol of solution: 0.2 mol solute and 0.8 mol water = 14.4 g = 0.0144 kg. Molality = 0.2/0.0144 = 13.9 mol/kg. 0.25 is just the mole ratio 0.2/0.8, not molality.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "chem-mole-concept-57", "question": "A gaseous mixture contains 2 mol of N₂ and 3 mol of O₂. Its average molar mass is:", "options": ["30.0 g/mol", "30.4 g/mol", "29.6 g/mol", "31.2 g/mol"], "answer": 1, "explanation": "Total mass = 2 × 28 + 3 × 32 = 56 + 96 = 152 g for 5 mol, so the average molar mass = 152/5 = 30.4 g/mol. 30.0 is the unweighted mean of 28 and 32.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-mole-concept-58", "question": "Oleum is labelled '109%', meaning 100 g of it gives 109 g of H₂SO₄ when diluted with just enough water. The percentage of free SO₃ by mass in this oleum is:", "options": ["9%", "40%", "20%", "49%"], "answer": 1, "explanation": "9 g of water is taken up: 9 g H₂O = 0.5 mol, which reacts with 0.5 mol SO₃ (SO₃ + H₂O → H₂SO₄). 0.5 mol SO₃ = 40 g, so free SO₃ = 40%. 9% is the water added, not the SO₃.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-mole-concept-59", "question": "A water sample contains 120 mg of MgSO₄ (molar mass 120) per litre. Its hardness expressed as ppm of CaCO₃ (molar mass 100) is:", "options": ["120 ppm", "144 ppm", "100 ppm", "83.3 ppm"], "answer": 2, "explanation": "120 mg MgSO₄ = 1 mmol, which is equivalent to 1 mmol = 100 mg of CaCO₃ per litre (≈ 10⁶ mg of water). Hardness = 100 ppm. 120 ppm just repeats the MgSO₄ mass.", "difficulty": "hard", "source": "JEE Main"},
  {"id": "chem-mole-concept-60", "question": "How many of the following statements are correct? (A) The molar mass of a substance in g/mol is numerically equal to its atomic or molecular mass in u. (B) One mole of electrons (mass 9.1 × 10⁻³¹ kg each) has a mass of about 0.55 mg. (C) 1 g of helium contains as many atoms as 1 g of hydrogen gas contains molecules. (D) In a binary solution the mole fractions of solute and solvent add up to 1.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "(A) true by the definition of the mole. (B) 9.1 × 10⁻³¹ × 6.022 × 10²³ = 5.48 × 10⁻⁷ kg ≈ 0.55 mg, true. (C) false: 1 g He = 1/4 mol atoms, while 1 g H₂ = 1/2 mol molecules. (D) true. Three are correct.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-mole-concept-61", "question": "25 mL of a solution containing both oxalic acid and sodium oxalate needs 20 mL of 0.1 M NaOH for neutralisation, and a separate 25 mL portion needs 50 mL of 0.02 M KMnO₄ in acidic medium. The molarity of sodium oxalate in the solution is:", "options": ["0.04 M", "0.06 M", "0.02 M", "0.1 M"], "answer": 1, "explanation": "Only H₂C₂O₄ reacts with NaOH: 2 mmol NaOH ÷ 2 = 1 mmol acid. KMnO₄ oxidises all oxalate: 1 mmol MnO₄⁻ × 5 = 5 meq = total oxalate × 2, so total oxalate = 2.5 mmol. Na₂C₂O₄ = 2.5 − 1 = 1.5 mmol in 25 mL = 0.06 M.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-mole-concept-62", "question": "10 mL of a gaseous hydrocarbon is mixed with 100 mL of O₂ (excess) and exploded. After cooling to room temperature the gas volume is 85 mL; after passing through KOH solution it falls to 65 mL. All volumes are at the same T and P. The hydrocarbon is:", "options": ["C₂H₄", "C₃H₆", "C₂H₂", "C₂H₆"], "answer": 3, "explanation": "KOH absorbs CO₂: 85 − 65 = 20 mL, so x = 2. For CₓHᵧ + (x + y/4)O₂ → xCO₂ + (y/2)H₂O(l), the contraction on cooling is 10(1 + y/4) = 110 − 85 = 25, giving y = 6. The gas is C₂H₆; C₂H₄ would give a contraction of only 20 mL.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-mole-concept-63", "question": "Assertion (A): Glucose (C₆H₁₂O₆) and acetic acid (C₂H₄O₂) have the same empirical formula. Reason (R): Glucose and acetic acid have the same molecular mass.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 2, "explanation": "Both reduce to CH₂O, so A is true. R is false: glucose has molar mass 180 and acetic acid 60; compounds with the same empirical formula can have different molecular formulas and masses.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-mole-concept-64", "question": "Match the sample (Column I) with the total number of atoms it contains (Column II). (a) 4.4 g CO₂, (b) 1.7 g NH₃, (c) 3.2 g CH₄, (d) 2.8 g N₂. (1) 0.2 N_A; (2) 0.3 N_A; (3) 0.4 N_A; (4) N_A.", "options": ["a-3, b-2, c-4, d-1", "a-2, b-3, c-4, d-1", "a-2, b-4, c-3, d-1", "a-1, b-3, c-4, d-2"], "answer": 1, "explanation": "(a) 0.1 mol × 3 atoms = 0.3 N_A. (b) 0.1 mol × 4 = 0.4 N_A. (c) 0.2 mol × 5 = 1.0 N_A. (d) 0.1 mol × 2 = 0.2 N_A. So a-2, b-3, c-4, d-1.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-mole-concept-65", "question": "When FeS₂ is oxidised to Fe³⁺ and SO₂, the n-factor of FeS₂ is:", "options": ["15", "7", "11", "3"], "answer": 2, "explanation": "Fe: +2 → +3 loses 1 e⁻. Each S: −1 → +4 loses 5 e⁻, and there are two S, so 10 e⁻. Total = 11. 15 would be the answer if sulphur went to +6 (sulphate).", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-mole-concept-66", "question": "A 1.5 g mixture of Mg and Al reacts completely with excess dilute HCl and gives 1.68 L of H₂ at STP (Mg = 24, Al = 27). The mass of Mg in the mixture is:", "options": ["0.6 g", "0.9 g", "0.75 g", "1.2 g"], "answer": 0, "explanation": "H₂ = 1.68/22.4 = 0.075 mol. Mg gives 1 H₂ per Mg and Al gives 1.5 H₂ per Al: x/24 + 1.5(1.5 − x)/27 = 0.075 → 3x + 4(1.5 − x) = 5.4 → x = 0.6 g. Check: 0.025 + 0.05 = 0.075 mol H₂.", "difficulty": "very-hard", "source": "JEE Main"},
  {"id": "chem-mole-concept-67", "question": "How many of the following statements are correct? (A) The law of conservation of mass was put forward by Lavoisier. (B) The law of definite proportions was given by Joseph Proust. (C) Dalton's atomic theory could explain Gay-Lussac's law of gaseous volumes. (D) Avogadro's law states that equal volumes of all gases at the same temperature and pressure contain equal numbers of atoms.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "(A) and (B) are correct. (C) is wrong: Dalton's theory could not explain the law of gaseous volumes; Avogadro's idea of molecules was needed. (D) is wrong: the law speaks of equal numbers of molecules, not atoms. Two are correct.", "difficulty": "very-hard", "source": "NEET"},
  {"id": "chem-mole-concept-68", "question": "The mass of KClO₃ (molar mass 122.5) that must be decomposed (2KClO₃ → 2KCl + 3O₂) to give enough oxygen to burn 2.4 g of carbon completely to CO₂ is about:", "options": ["24.5 g", "12.25 g", "8.17 g", "16.3 g"], "answer": 3, "explanation": "2.4 g C = 0.2 mol needs 0.2 mol O₂. KClO₃ needed = 0.2 × 2/3 = 0.133 mol = 0.133 × 122.5 = 16.3 g. 24.5 g takes KClO₃ : O₂ as 1 : 1; 8.17 g assumes the carbon burns only to CO.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id": "chem-mole-concept-69", "question": "0.664 g of the silver salt of a dibasic organic acid leaves 0.432 g of metallic silver on ignition (Ag = 108). The molar mass of the acid is:", "options": ["59", "166", "118", "332"], "answer": 2, "explanation": "Equivalent mass of the salt = 108 × 0.664/0.432 = 166. Replacing Ag (108) by H (1): equivalent mass of acid = 166 − 107 = 59. For a dibasic acid, molar mass = 2 × 59 = 118. 59 is only the equivalent mass.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id": "chem-mole-concept-70", "question": "100 mL of 0.1 M H₂SO₄ and 100 mL of 0.1 M HCl are mixed with 150 mL of 0.2 M NaOH. Which statement about the final solution is correct?", "options": ["Acidic; [Na⁺] ≈ 0.086 M", "Neutral; [Na⁺] ≈ 0.086 M", "Basic; [Na⁺] ≈ 0.12 M", "Neutral; [Na⁺] ≈ 0.15 M"], "answer": 1, "explanation": "H⁺ = 100 × 0.1 × 2 + 100 × 0.1 = 30 mmol; OH⁻ = 150 × 0.2 = 30 mmol, so the solution is exactly neutral. Na⁺ = 30 mmol in 350 mL = 0.086 M. Forgetting that H₂SO₄ is dibasic would wrongly make the solution basic.", "difficulty": "very-hard", "source": "JEE Main · NEET"},
  {"id":"chem-mole-concept-71","question":"When the redox equation MnO₄⁻ + C₂O₄²⁻ + H⁺ → Mn²⁺ + CO₂ + H₂O is balanced with the smallest whole-number coefficients, the coefficient of H⁺ is:","options":["16","10","8","5"],"answer":0,"explanation":"Mn goes +7 → +2 (gains 5 e⁻) and each C₂O₄²⁻ loses 2 e⁻, so 2MnO₄⁻ react with 5C₂O₄²⁻: 2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ → 2Mn²⁺ + 10CO₂ + 8H₂O. Balancing charge (−2 −10 + x = +4) fixes x = 16; 8 is the coefficient of water, not H⁺.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id": "chem-mole-concept-72", "question": "The equivalent mass of KMnO₄ (molar mass 158) when it is reduced to MnO₂ in a neutral or weakly alkaline medium is about:", "options": ["31.6", "52.7", "79.0", "158"], "answer": 1, "explanation": "In neutral/weakly alkaline medium Mn goes +7 → +4, so the n-factor is 3 and the equivalent mass is 158/3 ≈ 52.7. 31.6 is the acidic-medium value (n = 5, Mn²⁺) and 158 the strongly alkaline value (n = 1, MnO₄²⁻).", "difficulty": "moderate", "source": "JEE Main pattern"},
  {"id":"chem-mole-concept-73","question":"In the reaction 3Cu + 8HNO₃(dilute) → 3Cu(NO₃)₂ + 2NO + 4H₂O, the fraction of the nitric acid consumed that acts as an oxidising agent is:","options":["75%","100%","25%","50%"],"answer":2,"explanation":"Only the 2 N atoms that end up in NO change oxidation state (+5 → +2); the other 6 HNO₃ just supply NO₃⁻ to Cu(NO₃)₂. So 2/8 = 25% acts as oxidant; 75% is the fraction acting only as an acid.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"chem-mole-concept-74","question":"In hot concentrated NaOH, chlorine disproportionates: 3Cl₂ + 6OH⁻ → 5Cl⁻ + ClO₃⁻ + 3H₂O. Taking the n-factor of Cl₂ as the moles of electrons transferred per mole of Cl₂, the equivalent mass of Cl₂ (molar mass 71) is about:","options":["35.5","71.0","59.2","42.6"],"answer":3,"explanation":"Of 6 Cl atoms, 5 gain 1 e⁻ each and 1 loses 5 e⁻, so 5 electrons are transferred per 3 Cl₂: n = 5/3. Equivalent mass = 71 ÷ (5/3) = 42.6. 35.5 is what you get by treating Cl₂ like an ordinary oxidant going to Cl⁻ (n = 2).","difficulty":"hard","source":"JEE Advanced pattern"},
  {"id":"chem-mole-concept-75","question":"When Cr₂O₇²⁻ + H₂S + H⁺ → Cr³⁺ + S + H₂O is balanced with the smallest whole-number coefficients, the sum of ALL the coefficients (reactants and products) is:","options":["24","22","20","18"],"answer":0,"explanation":"Cr₂O₇²⁻ gains 6 e⁻ and each H₂S loses 2 e⁻, so Cr₂O₇²⁻ + 3H₂S + 8H⁺ → 2Cr³⁺ + 3S + 7H₂O (charge +6 = +6, O 7 = 7, H 14 = 14). Sum = 1 + 3 + 8 + 2 + 3 + 7 = 24; mis-balancing H⁺ or water; note that the 6 H of 3H₂S plus 8H⁺ supply all 14 H of the 7 waters gives the other totals.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-mole-concept-76", "question": "The volume of '20 volume' hydrogen peroxide needed to react completely with 25 mL of 0.1 M KMnO₄ in acidic medium is (volume strength refers to O₂ at STP, 22.4 L/mol):", "options": ["1.75 mL", "3.5 mL", "7.0 mL", "2.8 mL"], "answer": 1, "explanation": "20 vol H₂O₂: 20 L O₂ per litre = 20/22.4 mol O₂, so [H₂O₂] = 40/22.4 = 1.786 M and normality = 3.571 N (n = 2). KMnO₄: 25 × 0.1 × 5 = 12.5 meq, so V = 12.5/3.571 = 3.5 mL. Using the molarity instead of the normality gives 7.0 mL.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "chem-mole-concept-77", "question": "The mass of Mohr's salt, FeSO₄·(NH₄)₂SO₄·6H₂O (molar mass 392), that is exactly oxidised by 20 mL of 0.02 M K₂Cr₂O₇ in acidic medium is about:", "options": ["0.157 g", "0.470 g", "0.941 g", "0.314 g"], "answer": 2, "explanation": "Dichromate: 20 × 0.02 × 6 = 2.4 meq; Fe²⁺ → Fe³⁺ has n = 1, so 2.4 mmol of Mohr's salt = 2.4 × 392 mg = 0.941 g. Taking the n-factor of dichromate as 1 gives 0.157 g and as 3 gives 0.470 g; the ammonium sulphate part is not oxidised at all.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "chem-mole-concept-78", "question": "Excess KI is added to 25 mL of a CuSO₄ solution; the liberated iodine needs 20 mL of 0.1 M Na₂S₂O₃. The molarity of the CuSO₄ solution is:", "options": ["0.04 M", "0.16 M", "0.02 M", "0.08 M"], "answer": 3, "explanation": "2Cu²⁺ + 4I⁻ → 2CuI + I₂ and I₂ + 2S₂O₃²⁻ → 2I⁻ + S₄O₆²⁻, so Cu²⁺ : S₂O₃²⁻ = 1 : 1 (Cu²⁺ → Cu⁺ is a 1-electron change). Moles of Cu²⁺ = 2.0 mmol in 25 mL → 0.08 M; assuming Cu²⁺ → Cu (n = 2) gives the wrong 0.04 M.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id":"chem-mole-concept-79","question":"Thiosulphate is oxidised to tetrathionate by I₂ but to sulphate by Cl₂. The ratio of moles of Na₂S₂O₃ consumed by 1 mol of I₂ to that consumed by 1 mol of Cl₂ is:","options":["8 : 1","1 : 8","2 : 1","4 : 1"],"answer":0,"explanation":"With I₂: 2S₂O₃²⁻ → S₄O₆²⁻ + 2e⁻ (n = 1 per S₂O₃²⁻), so 1 mol I₂ (2 e⁻) uses 2 mol. With Cl₂: S (+2) → +6 for both S, n = 8, so 1 mol Cl₂ (2 e⁻) uses only 1/4 mol. Ratio = 2 : 0.25 = 8 : 1.","difficulty":"hard","source":"JEE Advanced pattern"},
  {"id":"chem-mole-concept-80","question":"In a weakly alkaline medium KMnO₄ oxidises iodide to iodate and is itself reduced to MnO₂. The moles of KMnO₄ required per mole of KI are:","options":["0.2","2","1.2","1/3"],"answer":1,"explanation":"I⁻ → IO₃⁻ is −1 → +5 (6 e⁻) and MnO₄⁻ → MnO₂ is a 3-electron gain, so 2 mol KMnO₄ per mol KI: 2MnO₄⁻ + I⁻ + H₂O → 2MnO₂ + IO₃⁻ + 2OH⁻. 1.2 assumes Mn²⁺ (n = 5) and 0.2 assumes the acidic products I₂ and Mn²⁺.","difficulty":"hard","source":"JEE Main pattern"},
  {"id": "chem-mole-concept-81", "question": "How many of the following statements about n-factors are correct? (A) The n-factor of H₃PO₂ acting as an acid is 1. (B) The n-factor of K₂Cr₂O₇ acting as an oxidant in acidic medium is 6. (C) The n-factor of KMnO₄ in strongly alkaline medium (product MnO₄²⁻) is 1. (D) The n-factor of Na₂S₂O₃ in its reaction with I₂ is 2.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A: H₃PO₂ has only one ionisable (O–H) hydrogen, n = 1 ✓. B: 2Cr (+6 → +3) = 6 ✓. C: Mn +7 → +6, n = 1 ✓. D is false: each S₂O₃²⁻ loses only 1 electron in forming S₄O₆²⁻ (average S +2 → +2.5), so n = 1. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-mole-concept-82","question":"1 mol each of FeC₂O₄, Fe₂(C₂O₄)₃ and FeSO₄ are mixed and oxidised completely by acidified KMnO₄. The total moles of KMnO₄ consumed are:","options":["1.8","2.4","2.0","3.0"],"answer":2,"explanation":"FeC₂O₄: Fe²⁺ (1 e⁻) + C₂O₄²⁻ (2 e⁻) = 3; Fe₂(C₂O₄)₃: Fe is already +3, only 3 oxalates oxidise = 6; FeSO₄: 1. Total 10 mol e⁻ ÷ 5 per MnO₄⁻ = 2.0 mol. Counting the Fe³⁺ of the ferric oxalate as oxidisable gives 12 e⁻ and the trap 2.4.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-mole-concept-83", "question": "0.50 g of pyrolusite is warmed with 50 mL of 0.1 M oxalic acid in dilute H₂SO₄ (MnO₂ + H₂C₂O₄ + 2H⁺ → Mn²⁺ + 2CO₂ + 2H₂O). The unreacted oxalic acid needs 20 mL of 0.02 M KMnO₄. The percentage of MnO₂ (molar mass 87) in the ore is:", "options": ["34.8%", "87.0%", "52.2%", "69.6%"], "answer": 3, "explanation": "Oxalic acid taken = 5.0 mmol; excess = (20 × 0.02) mmol KMnO₄ × 5/2 = 1.0 mmol. MnO₂ = 5.0 − 1.0 = 4.0 mmol = 348 mg → 348/500 = 69.6%. Forgetting the 5 : 2 ratio and taking excess oxalic acid = 0.4 mmol gives about 80%.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-mole-concept-84","question":"As₂S₃ is oxidised by nitric acid to H₃AsO₄ and H₂SO₄. If M is the molar mass of As₂S₃, its equivalent mass in this reaction is:","options":["M/28","M/22","M/24","M/4"],"answer":0,"explanation":"Both elements are oxidised: 2 As (+3 → +5) lose 4 e⁻ and 3 S (−2 → +6) lose 24 e⁻, so n = 28 and the equivalent mass is M/28. M/24 counts only sulphur, M/4 only arsenic, and M/22 comes from starting sulphur at 0 instead of −2.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-mole-concept-85","question":"Zinc reacts with very dilute nitric acid to give ammonium nitrate: 4Zn + 10HNO₃ → 4Zn(NO₃)₂ + NH₄NO₃ + 3H₂O. The moles of HNO₃ consumed per mole of Zn, and the fraction of the consumed HNO₃ that is actually reduced, are respectively:","options":["2.5 and 1/5","2.5 and 1/10","2.0 and 1/8","2.25 and 1/9"],"answer":1,"explanation":"4 Zn give 8 e⁻, which reduce exactly one N (+5 → −3); so 10 HNO₃ per 4 Zn = 2.5 per Zn. Of the 10 N atoms, only the one in NH₄⁺ is reduced (1/10); the NO₃⁻ of NH₄NO₃ is unchanged, which is why 1/5 is wrong.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-mole-concept-86","question":"25 mL of a solution containing NaOH and Na₂CO₃ needs 20 mL of 0.1 M HCl to reach the phenolphthalein end point, and a further 5 mL of the same acid to reach the methyl orange end point. The masses of NaOH and Na₂CO₃ in the 25 mL are respectively:","options":["40 mg and 106 mg","80 mg and 53 mg","60 mg and 53 mg","60 mg and 106 mg"],"answer":2,"explanation":"The second titre (CO₃²⁻ already converted to HCO₃⁻ → H₂CO₃) gives Na₂CO₃ = 0.5 mmol = 53 mg. The first titre covers NaOH + Na₂CO₃ → NaHCO₃: 2.0 − 0.5 = 1.5 mmol NaOH = 60 mg. Doubling the second titre for carbonate (it is only the second half of its neutralisation) gives the 40 mg / 106 mg trap.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-mole-concept-87","question":"100 mL of 0.02 M KMnO₄ reacts completely with excess H₂O₂ in acidic medium. The volume of O₂ evolved at STP is (22.4 L/mol):","options":["44.8 mL","56 mL","224 mL","112 mL"],"answer":3,"explanation":"2MnO₄⁻ + 5H₂O₂ + 6H⁺ → 2Mn²⁺ + 5O₂ + 8H₂O: every O₂ comes from H₂O₂ (O −1 → 0), 5 O₂ per 2 MnO₄⁻. 2 mmol KMnO₄ → 5 mmol O₂ = 112 mL. Assuming the oxygen comes from permanganate (or 1 : 1) gives 44.8 mL.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "chem-mole-concept-88", "question": "How many of the following statements are correct? (A) The oxidation state of Cr in CrO₅ is +10. (B) The oxidation state of S in H₂SO₅ is +6. (C) The oxidation state of O in KO₂ is −1/2. (D) In S₄O₆²⁻ every sulphur atom has the oxidation state +2.5.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "CrO₅ has two peroxo groups, so Cr is +6, not +10 (A false); H₂SO₅ contains one peroxo O–O, so S is +6 (B true); superoxide O₂⁻ gives −1/2 (C true). In S₄O₆²⁻ +2.5 is only the average: the two bridging S are 0 and the two terminal S are +5 (D false). Two are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"chem-mole-concept-89","question":"2.4 g of magnesium is burnt completely in air, forming 3.8 g of a mixture of MgO and Mg₃N₂ (Mg = 24, N = 14). The product is then treated with excess water. The volume of NH₃ released at STP is:","options":["448 mL","224 mL","672 mL","112 mL"],"answer":0,"explanation":"Let a mol MgO and b mol Mg₃N₂: a + 3b = 0.1 and 40a + 100b = 3.8, giving b = 0.01, a = 0.07. Mg₃N₂ + 6H₂O → 3Mg(OH)₂ + 2NH₃, so NH₃ = 0.02 mol = 448 mL. Forgetting the factor 2 in the hydrolysis gives 224 mL.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id": "chem-mole-concept-90", "question": "K₄[Fe(CN)₆] is oxidised by acidified KMnO₄ to Fe³⁺, CO₂ and NO₃⁻. The number of moles of KMnO₄ needed per mole of K₄[Fe(CN)₆] is:", "options": ["0.2", "12.2", "1.2", "61"], "answer": 1, "explanation": "Electrons lost per formula unit: Fe²⁺ → Fe³⁺ = 1; each CN⁻ has C +2 → +4 (2) and N −3 → +5 (8), so 6 × 10 = 60; total n = 61. KMnO₄ (n = 5) needed = 61/5 = 12.2 mol. Counting only Fe oxidation gives the trap 0.2.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-mole-concept-91","question":"100 mL of 0.2 M BaCl₂ is mixed with 100 mL of 0.15 M Na₂SO₄ (Ba = 137, S = 32). Which statement about the result is correct?","options":["3.50 g of BaSO₄ precipitates and [Ba²⁺] left is 0.05 M","4.66 g of BaSO₄ precipitates and [Cl⁻] is 0.20 M","3.50 g of BaSO₄ precipitates and [Cl⁻] in solution is 0.20 M","3.50 g of BaSO₄ precipitates and [SO₄²⁻] left is 0.025 M"],"answer":2,"explanation":"Ba²⁺ = 20 mmol, SO₄²⁻ = 15 mmol, so sulphate is limiting: 15 mmol BaSO₄ × 233 = 3.50 g. Left in 200 mL: Ba²⁺ 5 mmol (0.025 M), no sulphate, and Cl⁻ 40 mmol = 0.20 M (spectator ions are diluted, not consumed). 0.05 M forgets the volume doubling.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-mole-concept-92","question":"Equal masses of oxalic acid dihydrate are titrated separately with 0.1 M NaOH and with 0.1 M KMnO₄ (acidic medium). The ratio of the volume of NaOH to the volume of KMnO₄ used is:","options":["1 : 1","1 : 5","2 : 5","5 : 1"],"answer":3,"explanation":"Per mole of H₂C₂O₄, NaOH needed = 2 mol (dibasic) and KMnO₄ needed = 2/5 mol (2MnO₄⁻ : 5C₂O₄²⁻). At equal molarity the volumes are in the ratio 2 : 0.4 = 5 : 1. 1 : 1 would be right only if both were 0.1 N, not 0.1 M.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id": "chem-mole-concept-93", "question": "When Cr(OH)₃ + IO₃⁻ → CrO₄²⁻ + I⁻ is balanced in basic medium with the smallest whole-number coefficients, the coefficients of OH⁻ and H₂O are respectively:", "options": ["4 and 5", "2 and 5", "4 and 3", "5 and 4"], "answer": 0, "explanation": "Cr +3 → +6 (3 e⁻ each) and I +5 → −1 (6 e⁻), so 2Cr(OH)₃ + IO₃⁻. Balancing charge and O: 2Cr(OH)₃ + IO₃⁻ + 4OH⁻ → 2CrO₄²⁻ + I⁻ + 5H₂O (charge −5 = −5; O 13 = 13; H 10 = 10). Water appears on the product side, which is the usual slip.", "difficulty": "very-hard", "source": "JEE Advanced pattern"},
  {"id":"chem-mole-concept-94","question":"An aqueous urea solution (molar mass of urea 60) has a molarity and a molality that are both numerically equal to 2. The density of the solution is:","options":["1.00 g/mL","1.12 g/mL","1.24 g/mL","1.06 g/mL"],"answer":1,"explanation":"1 L of solution has 2 mol urea = 120 g. For molality to be 2, this must be dissolved in exactly 1000 g of water, so 1 L weighs 1120 g and d = 1.12 g/mL. In general m = M only when d = 1 + M × (molar mass)/1000; d = 1.00 ignores the mass of the solute.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-mole-concept-95","question":"10 mL of a sulphuric acid sample is diluted to 100 mL. 25 mL of the diluted solution needs 20 mL of 0.1 M NaOH for neutralisation. If the original acid has density 1.2 g/mL, its strength in % (w/w) is about:","options":["1.63%","6.53%","3.27%","3.92%"],"answer":2,"explanation":"NaOH = 2.0 mmol → H₂SO₄ = 1.0 mmol in 25 mL → 0.04 M diluted → 0.40 M original = 39.2 g/L. Mass % = 39.2/1200 × 100 = 3.27%. Forgetting that H₂SO₄ is dibasic gives 6.53%, and ignoring the density (dividing by 1000) gives 3.92%.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-mole-concept-96","question":"The number of moles of Na⁺ ions present in 14.2 g of anhydrous Na₂SO₄ (molar mass 142 g/mol) is:","options":["0.1","0.2","0.3","0.4"],"answer":1,"explanation":"14.2 g ÷ 142 g/mol = 0.1 mol Na₂SO₄. Each formula unit releases two Na⁺ ions, so moles of Na⁺ = 2 × 0.1 = 0.2. 0.1 counts formula units, and 0.3 counts all ions.","difficulty":"easy","source":"NEET · JEE Main"},
  {"id":"chem-mole-concept-97","question":"The mass of 0.25 mol of glucose (C₆H₁₂O₆) is:","options":["45 g","72 g","30 g","180 g"],"answer":0,"explanation":"Molar mass of glucose = 6(12) + 12(1) + 6(16) = 180 g/mol. Mass = 0.25 × 180 = 45 g.","difficulty":"easy","source":"NEET"},
  {"id":"chem-mole-concept-98","question":"A pure gas has a density of 2.86 g/L at STP (molar volume 22.4 L). The gas could be:","options":["C₂H₆","NO₂","Cl₂","SO₂"],"answer":3,"explanation":"Molar mass = density × molar volume = 2.86 × 22.4 ≈ 64 g/mol, which matches SO₂. NO₂ (46) would have density 2.05 g/L and Cl₂ (71) about 3.17 g/L; C₂H₆ (30) is far lighter.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-99","question":"50 mL of 0.2 M AlCl₃ is mixed with 150 mL of 0.1 M MgCl₂. Assuming complete dissociation, the molar concentration of Cl⁻ in the mixture is:","options":["0.15 M","0.6 M","0.3 M","0.125 M"],"answer":2,"explanation":"Cl⁻ from AlCl₃ = 50 × 0.2 × 3 = 30 mmol; from MgCl₂ = 150 × 0.1 × 2 = 30 mmol. Total 60 mmol in 200 mL gives 0.3 M. Ignoring the 3 and 2 chloride ions per formula unit gives 0.125 M.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-mole-concept-100","question":"Na₂CO₃ (molar mass 106) is titrated with HCl using phenolphthalein as the indicator. Its equivalent mass in this titration is:","options":["212","106","35.3","53"],"answer":1,"explanation":"With phenolphthalein the end point comes when CO₃²⁻ has taken up only one proton (CO₃²⁻ + H⁺ → HCO₃⁻), so the n-factor is 1 and the equivalent mass is 106. With methyl orange the conversion goes to H₂CO₃ (n = 2) and the equivalent mass would be 53.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-mole-concept-101","question":"0.45 g of a trivalent metal reacts completely with dilute acid and liberates 560 mL of H₂ measured at STP. The atomic mass of the metal is:","options":["27","40.5","18","9"],"answer":0,"explanation":"H₂ = 0.560/22.4 = 0.025 mol. A trivalent metal gives 3/2 mol H₂ per mol (2M + 6H⁺ → 2M³⁺ + 3H₂), so metal = 0.025 × 2/3 = 0.01667 mol. Atomic mass = 0.45/0.01667 = 27 (aluminium). Equivalent mass is 9; taking it as the atomic mass is the trap.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-102","question":"0.5 L of a 0.2 M aqueous solution of K₄[Fe(CN)₆] is prepared. Assuming the complex dissociates only into its constituent ions K⁺ and [Fe(CN)₆]⁴⁻, the total number of ions present is (N_A = 6.022 × 10²³):","options":["6.022 × 10²²","1.024 × 10²⁴","2.409 × 10²³","3.011 × 10²³"],"answer":3,"explanation":"Moles of complex = 0.5 × 0.2 = 0.1 mol. Each formula unit gives 4 K⁺ + 1 [Fe(CN)₆]⁴⁻ = 5 ions, so 0.5 mol ions = 3.011 × 10²³. The cyanide ligands stay bound to iron; counting them as free ions gives the 1.024 × 10²⁴ trap.","difficulty":"moderate","source":"JEE Main"},
  {"id":"chem-mole-concept-103","question":"A trivalent metal M forms a chloride MCl₃ that contains 79.8% chlorine by mass. The atomic mass of M is closest to:","options":["54","18","27","9"],"answer":2,"explanation":"In MCl₃, 3 × 35.5 = 106.5 g Cl corresponds to 79.8% of the molar mass, so molar mass = 106.5/0.798 ≈ 133.5. Atomic mass of M = 133.5 − 106.5 = 27. The equivalent mass is 9, which is the value obtained if one forgets the valency.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-104","question":"A hydrocarbon contains carbon and hydrogen in the mass ratio 9 : 2. Its empirical formula is:","options":["C₉H₂","C₃H₈","C₂H₆","C₃H₄"],"answer":1,"explanation":"Mole ratio C : H = 9/12 : 2/1 = 0.75 : 2 = 3 : 8, so the empirical formula is C₃H₈. Writing the mass ratio directly as the atom ratio gives the absurd C₉H₂.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-mole-concept-105","question":"20 mL of a gaseous mixture of CO, CH₄ and N₂ is exploded with excess O₂. On cooling to room temperature the volume contracts by 13 mL, and a further 14 mL is absorbed by aqueous KOH. All volumes are at the same T and P. The volume of N₂ in the original mixture is:","options":["6 mL","4 mL","10 mL","2 mL"],"answer":0,"explanation":"Let CO = a and CH₄ = b. CO + ½O₂ → CO₂ contracts by a/2; CH₄ + 2O₂ → CO₂ + 2H₂O(l) contracts by 2b. So a/2 + 2b = 13, and CO₂ formed a + b = 14. Solving: b = 4 mL, a = 10 mL, hence N₂ = 20 − 14 = 6 mL. N₂ is inert and appears in neither measurement.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-mole-concept-106","question":"10.0 g of aluminium powder is ignited with 30.0 g of Fe₂O₃ (Fe = 56, Al = 27): 2Al + Fe₂O₃ → Al₂O₃ + 2Fe. The maximum mass of iron obtained is about:","options":["10.4 g","29.6 g","21.0 g","20.7 g"],"answer":3,"explanation":"Fe₂O₃ = 30/160 = 0.1875 mol, which would need 0.375 mol (10.1 g) Al; only 10/27 = 0.370 mol Al is present, so Al is limiting. Fe formed = 0.370 mol × 56 = 20.7 g. Taking Fe₂O₃ as limiting gives 21.0 g.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-mole-concept-107","question":"1.0 g of an impure CaCO₃ sample is dissolved in 50 mL of 0.5 M HCl. The excess acid requires 20 mL of 0.5 M NaOH for neutralisation. The percentage purity of the CaCO₃ is (impurities are inert):","options":["62.5%","50%","75%","37.5%"],"answer":2,"explanation":"HCl taken = 25 mmol; HCl left = 10 mmol (by NaOH), so 15 mmol HCl reacted with CaCO₃. CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂, so CaCO₃ = 7.5 mmol = 0.75 g, i.e. 75%. Forgetting the 1 : 2 ratio doubles the answer to an impossible 150%, and using the leftover acid gives 50%.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-108","question":"A 2.0 M aqueous glucose solution (molar mass 180) has a density of 1.20 g/mL. The mole fraction of glucose in it is about:","options":["0.036","0.041","0.048","0.020"],"answer":1,"explanation":"1 L of solution weighs 1200 g and contains 2 × 180 = 360 g glucose, so water = 840 g = 46.67 mol. x(glucose) = 2/(2 + 46.67) = 0.041. Assuming 1000 g of water (confusing molarity with molality) gives 0.035.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-mole-concept-109","question":"50 mL of '11.2 volume' H₂O₂ is diluted with water to 200 mL. The normality of the diluted solution (H₂O₂ acting as an oxidant or reductant) is:","options":["0.5 N","1.0 N","2.0 N","0.25 N"],"answer":0,"explanation":"Volume strength = 11.2 × molarity, so 11.2 volume H₂O₂ is 1 M, i.e. 2 N (n-factor 2). A four-fold dilution gives 0.5 N. 0.25 N is the diluted molarity.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-mole-concept-110","question":"Cu₂S is oxidised to Cu²⁺ and SO₂. If M is the molar mass of Cu₂S, its equivalent mass in this reaction is:","options":["M/10","M/6","M/2","M/8"],"answer":3,"explanation":"Each Cu goes +1 → +2 (2 e⁻ for two Cu) and S goes −2 → +4 (6 e⁻). Total n-factor = 8, so equivalent mass = M/8. If sulphur were oxidised to sulphate (+6) the n-factor would be 10.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-mole-concept-111","question":"10 L of a mixture of CH₄ and C₂H₆ needs exactly 26 L of O₂ for complete combustion, all volumes at the same T and P. The volume of CO₂ produced is:","options":["10 L","16 L","14 L","12 L"],"answer":2,"explanation":"Let CH₄ = x and C₂H₆ = y: x + y = 10 and 2x + 3.5y = 26, so y = 4 L and x = 6 L. CO₂ = x + 2y = 6 + 8 = 14 L. 10 L assumes each hydrocarbon gives one CO₂.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-mole-concept-112","question":"An oxide of iron contains 72.4% iron by mass (Fe = 56). Its formula is:","options":["Fe₂O₃","Fe₃O₄","Fe₄O₅","FeO"],"answer":1,"explanation":"Fe : O mole ratio = 72.4/56 : 27.6/16 = 1.293 : 1.725 = 3 : 4, so the oxide is Fe₃O₄. FeO has 77.8% Fe and Fe₂O₃ has 70% Fe.","difficulty":"hard","source":"NEET · JEE Main"},
  {"id":"chem-mole-concept-113","question":"25 mL of a solution containing both Fe²⁺ and Fe³⁺ requires 20 mL of 0.02 M KMnO₄ in acidic medium. Another 25 mL portion is first reduced completely with zinc and then needs 30 mL of the same KMnO₄. The molarity of Fe³⁺ in the original solution is:","options":["0.04 M","0.02 M","0.08 M","0.12 M"],"answer":0,"explanation":"First titration: Fe²⁺ = 20 × 0.02 × 5 = 2 mmol. After Zn reduction all iron is Fe²⁺: 30 × 0.02 × 5 = 3 mmol. So Fe³⁺ = 3 − 2 = 1 mmol in 25 mL = 0.04 M. 0.12 M is the total iron concentration.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"chem-mole-concept-114","question":"0.214 g of KIO₃ (molar mass 214) is treated with excess KI in acid: IO₃⁻ + 5I⁻ + 6H⁺ → 3I₂ + 3H₂O. The liberated iodine needs 30.0 mL of Na₂S₂O₃ for decolourisation. The molarity of the thiosulphate solution is:","options":["0.033 M","0.1 M","0.067 M","0.2 M"],"answer":3,"explanation":"KIO₃ = 1 mmol, giving 3 mmol I₂. Since I₂ + 2S₂O₃²⁻ → 2I⁻ + S₄O₆²⁻, thiosulphate = 6 mmol, and 6/30 = 0.2 M. Forgetting that one iodate produces three I₂ gives 0.067 M.","difficulty":"very-hard","source":"JEE Main · JEE Advanced"},
  {"id":"chem-mole-concept-115","question":"A 5.00 g mixture of NaCl and KCl is dissolved and treated with excess AgNO₃, giving 10.68 g of AgCl (Na = 23, K = 39, Cl = 35.5, Ag = 108). The percentage of NaCl in the mixture is about:","options":["50%","35%","40%","60%"],"answer":2,"explanation":"Let NaCl = x g: x/58.5 + (5 − x)/74.5 = 10.68/143.5 = 0.07443 mol. Solving, x ≈ 2.0 g, so NaCl ≈ 40%. Each chloride ion gives one AgCl, which links the two unknowns.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-mole-concept-116","question":"The number of gas molecules in 1.0 mL of an ideal gas at 27 °C and 1 atm is about (k_B = 1.38 × 10⁻²³ J/K):","options":["4.46 × 10¹⁹","2.45 × 10¹⁹","2.69 × 10¹⁹","6.02 × 10²⁰"],"answer":1,"explanation":"N = PV/(k_B T) = (101325 × 10⁻⁶)/(1.38 × 10⁻²³ × 300) ≈ 2.45 × 10¹⁹. The Loschmidt-type value 2.69 × 10¹⁹ applies at 273 K, not 300 K.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-mole-concept-117","question":"When the equation S + HNO₃ → H₂SO₄ + NO₂ + H₂O is balanced with the smallest whole-number coefficients, the sum of all the coefficients is:","options":["16","14","12","18"],"answer":0,"explanation":"S goes 0 → +6 (6 e⁻ lost) and each N goes +5 → +4 (1 e⁻ gained), so 6 HNO₃ per S: S + 6HNO₃ → H₂SO₄ + 6NO₂ + 2H₂O. H: 6 = 2 + 4 ✓; O: 18 = 4 + 12 + 2 ✓. Sum = 1 + 6 + 1 + 6 + 2 = 16.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"chem-mole-concept-118","question":"The mass of O₂ needed to convert 5.6 g of iron (Fe = 56) completely into Fe₃O₄ is about:","options":["2.40 g","3.20 g","1.60 g","2.13 g"],"answer":3,"explanation":"Fe = 0.1 mol forms 0.1/3 mol Fe₃O₄, containing 0.1333 mol O atoms = 0.0667 mol O₂ = 2.13 g. 1.60 g corresponds to FeO and 2.40 g to Fe₂O₃.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-119","question":"4.8 g of Mg is heated in 2.24 L of N₂ (at STP) until reaction is complete, forming Mg₃N₂. The product is then hydrolysed completely with water. The volume of NH₃ evolved at STP is about:","options":["2.24 L","4.48 L","2.99 L","1.49 L"],"answer":2,"explanation":"Mg = 0.2 mol and N₂ = 0.1 mol; 3Mg + N₂ → Mg₃N₂ needs only 0.0667 mol N₂, so Mg is limiting and Mg₃N₂ = 0.0667 mol. Mg₃N₂ + 6H₂O → 3Mg(OH)₂ + 2NH₃ gives 0.1333 mol NH₃ = 2.99 L. 4.48 L wrongly takes N₂ as limiting.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-mole-concept-120","question":"46 g of ethanol is dehydrated to ethene in 80% yield, and the ethene is then converted to 1,2-dibromoethane (molar mass 188) in 75% yield. The mass of 1,2-dibromoethane obtained is about:","options":["188 g","113 g","150 g","141 g"],"answer":1,"explanation":"Ethanol = 1 mol. Overall yield = 0.80 × 0.75 = 0.60, so 0.6 mol C₂H₄Br₂ = 0.6 × 188 ≈ 113 g. 150 g applies only the 80% step and 141 g only the 75% step.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-mole-concept-121","question":"Equal masses of potassium tetroxalate, KHC₂O₄·H₂C₂O₄·2H₂O, are titrated separately (i) with 0.1 M NaOH and (ii) with 0.02 M KMnO₄ in acidic medium. The ratio of the volumes V(NaOH) : V(KMnO₄) is:","options":["3 : 4","3 : 2","1 : 1","4 : 3"],"answer":0,"explanation":"As an acid the salt has 3 replaceable H⁺ (n = 3); as a reductant it has two C₂O₄ units each losing 2 e⁻ (n = 4). For 1 mol: V(NaOH) ∝ 3/0.1 = 30 and V(KMnO₄) ∝ 4/(0.02 × 5) = 40, so the ratio is 3 : 4.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-mole-concept-122","question":"A solution of ethanol in water has an ethanol mole fraction of 0.25 and a density of 0.90 g/mL. Its molarity is about:","options":["10.0 M","18.5 M","13.9 M","9.0 M"],"answer":3,"explanation":"Take 1 mol of solution: 0.25 mol ethanol (11.5 g) + 0.75 mol water (13.5 g) = 25 g, volume = 25/0.90 = 27.8 mL. Molarity = 0.25/0.0278 = 9.0 M. 18.5 m is the molality (0.25 mol per 13.5 g water).","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-mole-concept-123","question":"1.00 g of NaOH contaminated only with Na₂CO₃ requires 24.0 mL of 1.0 M HCl for complete neutralisation to the methyl orange end point. The percentage of NaOH in the sample is about:","options":["96.0%","75.0%","83.7%","16.3%"],"answer":2,"explanation":"With methyl orange, Na₂CO₃ uses 2 HCl. If NaOH = x g: x/40 + 2(1 − x)/106 = 0.024, giving x = 0.837 g, i.e. 83.7%. 96% assumes the sample is all NaOH (0.024 × 40 g), and 16.3% is the carbonate content.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-mole-concept-124","question":"A metal M forms two oxides containing 27.6% and 30.0% oxygen by mass. If the first oxide is M₃O₄, the formula of the second is:","options":["MO₂","M₂O₃","M₂O₅","MO"],"answer":1,"explanation":"O per unit mass of M: 27.6/72.4 = 0.381 and 30.0/70.0 = 0.429, ratio 8 : 9. The first has O/M = 4/3, so the second has O/M = (4/3)(9/8) = 3/2, i.e. M₂O₃. These are the two common oxides of iron (law of multiple proportions).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"chem-mole-concept-125","question":"100 mL of NH₃ is partially decomposed (2NH₃ → N₂ + 3H₂) at constant T and P, and the total volume becomes 140 mL. The percentage of NH₃ decomposed is:","options":["40%","60%","20%","80%"],"answer":0,"explanation":"If x mL NH₃ decomposes it gives x/2 mL N₂ + 3x/2 mL H₂, a net increase of x mL. The increase is 40 mL, so x = 40 mL = 40%. Assuming every 2 volumes give 4 volumes and halving the increase gives 20%.","difficulty":"hard","source":"JEE Main"},
  {"id":"chem-mole-concept-126","question":"100 mL of O₂ is passed through an ozoniser and the volume falls to 90 mL (same T and P). The gas is then passed through turpentine oil, which absorbs ozone. The final volume of gas is:","options":["80 mL","90 mL","60 mL","70 mL"],"answer":3,"explanation":"3O₂ → 2O₃: a decrease of 1 volume per 2 volumes of O₃ formed, so a 10 mL decrease means 20 mL O₃. Absorbing 20 mL O₃ from 90 mL leaves 70 mL of O₂. 80 mL equates O₃ formed with the contraction.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-mole-concept-127","question":"50 mL of 0.2 M AgNO₃ is mixed with 50 mL of 0.3 M NaCl. After precipitation of AgCl is complete, the concentration of Cl⁻ left in solution is (ignore the solubility of AgCl):","options":["0.15 M","0.025 M","0.05 M","0.10 M"],"answer":2,"explanation":"Ag⁺ = 10 mmol and Cl⁻ = 15 mmol; 10 mmol AgCl precipitates and 5 mmol Cl⁻ remains in 100 mL, giving 0.05 M. 0.10 M forgets that the volume has doubled on mixing.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"chem-mole-concept-128","question":"In a Victor Meyer determination, 0.20 g of a volatile liquid displaces 60.0 mL of air measured (dry) at 300 K and 1 atm (R = 0.0821 L atm K⁻¹ mol⁻¹). The molar mass of the liquid is about:","options":["164 g/mol","82 g/mol","75 g/mol","41 g/mol"],"answer":1,"explanation":"The displaced air volume equals the vapour volume: n = PV/RT = (1 × 0.060)/(0.0821 × 300) = 2.44 × 10⁻³ mol. Molar mass = 0.20/0.00244 ≈ 82 g/mol. Using 22.4 L/mol at STP without correcting the temperature gives about 75.","difficulty":"very-hard","source":"JEE Main"},
  {"id":"chem-mole-concept-129","question":"Haemoglobin contains 0.34% iron by mass and has a molar mass of about 66,000 g/mol (Fe = 56). The number of iron atoms per haemoglobin molecule is:","options":["4","1","2","6"],"answer":0,"explanation":"Mass of Fe per mole = 0.0034 × 66,000 ≈ 224 g, and 224/56 = 4 Fe atoms. The minimum molar mass with one Fe would be 56/0.0034 ≈ 16,500, a quarter of the actual value.","difficulty":"very-hard","source":"NEET · JEE Main"},
];

